package com.auramirage.app
import android.content.Context
import android.speech.tts.*
import java.util.Locale
class ReaderController(c:Context,private val state:(String)->Unit):TextToSpeech.OnInitListener{private val tts=TextToSpeech(c.applicationContext,this);private var ready=false;var selectedVoiceName:String?=null;private set;override fun onInit(s:Int){if(s!=TextToSpeech.SUCCESS){state("Falha ao iniciar voz");return};val l=Locale.forLanguageTag("pt-BR");if(tts.isLanguageAvailable(l)<TextToSpeech.LANG_AVAILABLE){state("Voz pt-BR indisponível");return};tts.language=l;ready=true;state("Voz pt-BR pronta")};fun voices():List<Voice> =if(ready)tts.voices.filter{it.locale.language=="pt"}else emptyList();fun selectVoice(v:Voice){if(ready){tts.voice=v;selectedVoiceName=v.name;state("Voz: ${v.name}")}};fun speak(text:String){if(!ready){state("A voz ainda está carregando");return};tts.stop();tts.setOnUtteranceProgressListener(object:UtteranceProgressListener(){override fun onStart(id:String?){state("Lendo")};override fun onDone(id:String?){state("Concluído")};override fun onError(id:String?){state("Erro na leitura")}});tts.speak(text,TextToSpeech.QUEUE_FLUSH,null,"note-${System.currentTimeMillis()}")};fun stop(){tts.stop();state("Parado")};fun shutdown(){tts.shutdown()}}
